INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(1400, 0, 14, 0, 0, 0, 'Durotar', 'Durotar is a hard country of red rock, scrub and baking heat on the eastern shore of Kalimdor, and it is the homeland Thrall claimed for the orcs after the battle at Mount Hyjal. He named it for his father, Durotan, and raised its great city, Orgrimmar, in the northern mountains. The land was not empty when the orcs came. Razormane quilboar held much of it and still lurk behind their brambles, Kolkar centaurs camp in the southern crags, and Dustwind harpies plunder the caravans. Soldiers of Kul Tiras, left behind when Admiral Proudmoore fell, hold a keep on the eastern coast, and the demon cult of the Burning Blade hides in caves and gorges from the Valley of Trials to the very walls of the capital. The Darkspear trolls, sworn allies of the Horde, share the land from Sen''jin Village, exiled from their Echo Isles by the witch doctor Zalazane. At Razor Hill, Gar''Thok keeps watch over it all.', 'warcraft.wiki.gg/wiki/Durotar (named after Durotan, founded after Mount Hyjal, Razormane held the land, Kul Tiras fleet, geography); quest 837 description (Razormane possessed much of the land); quest 784 description (Kul Tiras reserves at Tiragarde); quest 786 description (Kolkar); quest 834 description (harpies and caravans); quest 828 description (Skull Rock just outside Orgrimmar); quest 826 description (Zalazane on the Echo Isles); quest 785 description (pact of protection with the Darkspear)'),
(1401, 1, 14, 1, 0, 0, 'Valley of Trials', 'Hemmed in by red cliffs in the south of Durotar, the Valley of Trials is where young orcs and trolls come of age. Kaltunk greets each recruit and sends them on to Gornek, who keeps to the Den, a cave cut into the valley''s heart where trainers of every calling wait. Mottled boars root to the north, scorpid workers swarm the slopes, and peons gather lumber from the few trees that grow here, when they are not caught napping. Even this proving ground is not clean: imps and felstalkers spill from a cave in the northern cliffs, where the Burning Blade has made a coven of its own.', 'warcraft.wiki.gg/wiki/Valley_of_Trials (southern Durotar, The Den carved into the cliffs, trainers, peons gather lumber, coven in the northern cliffs); quest 4641 description (Kaltunk sends recruits to Gornek in the Den); quests 788, 789 descriptions (boars north, scorpids); quest 5441 description (lazy peons); quest 792 description (coven in the valley); DB spawns: Mottled Boar, Scorpid Worker, Vile Familiar, Felstalker, Lazy Peon in area 363; class trainers around the Den'),
(1402, 1, 14, 2, 0, 0, 'Burning Blade Coven', 'The caves in the northern cliffs of the Valley of Trials were once just caves. Foreman Thazz''ril surveyed them for ore and left his favorite pick in a chamber of waterfalls, only to return and find the place full of vicious beasts. The Burning Blade had moved in. Vile familiars and felstalkers now creep out into the valley, and deep inside, the warlock Yarrog Baneshadow guards a medallion of dark power. That a demon cult dares to nest beside the Horde''s own training ground is a warning that it has wider designs on Durotar.', 'warcraft.wiki.gg/wiki/Burning_Blade_Coven (northern border of the valley, led by Yarrog Baneshadow, imps spill out); quest 6394 description (Thazz''ril''s pick, chamber with waterfalls, cave filled with beasts); quest 794 description and reward text (medallion, further aims in our land); creature_loot: Yarrog Baneshadow 3183 drops Burning Blade Medallion 4859'),
(1403, 1, 14, 3, 0, 0, 'Spirit Rock', 'Southwest of the Valley of Trials, at the end of a narrow way the shaman call the Hidden Path, stands Spirit Rock. It is holy ground. Here young orc and troll shaman drink the earth sapta, a draught that binds the spirit to an element, for such a drink may only be taken in a sacred place. Those who drink it see what others cannot: the earth itself stands before them as a living presence and judges whether they are ready. Earth spirits of red stone linger nearby.', 'quest 1517 description (Spirit Rock southwest of Canaga, end of the Hidden Path, sapta drunk only in a holy place); quest 1517 reward text and 1518 description (meeting the earth); DB: Shaman Shrine 101749, Minor Manifestation of Earth 5891 and Redrock Earth Spirit 5890 in area 639; area 638 Hidden Path adjoins 639 on the map grid'),
(1404, 1, 14, 4, 0, 0, 'Sen''jin Village', 'When Zalazane''s dark voodoo drove them from the Echo Isles, the free Darkspear trolls built Sen''jin Village on the strand of southern Durotar, and named it for Sen''jin, Vol''jin''s father, the chieftain slain by murlocs on the isles where the tribe first met Thrall. The old witch doctor Master Gadrin speaks for the village, with his assistant Bom''bay at his side, while the hunter Vel''rin Fang trades in tiger hides, the alchemist Master Vornal, whose eyes are failing, tests would be apprentices, and the scout Lar Prowltusk watches the western flank for centaurs. A raptor handler and a mage of the tribe make their homes here too.', 'warcraft.wiki.gg/wiki/Sen''jin_Village (Darkspear fled Zalazane, named by Vol''jin after his father Sen''jin); warcraft.wiki.gg/wiki/Echo_Isles (Vol''jin founded Sen''jin Village at Darkspear Strand); quests 805, 808, 826 (Master Gadrin); npc_text 3794, 3795 (Bom''bay, Gadrin''s assistant); quest 817 (Vel''rin Fang hides); quest 818 (Vornal''s eyes fail, refuses unworthy apprentices); quest 785 and 786 (Lar Prowltusk watching the western flank, Kolkar to the west); DB: Zjolnir raptor handler, Ula''elek, Un''Thuwa in area 367; warcraft.wiki.gg/wiki/Sen''jin (sacrificed by a murloc sorcerer; village named in his memory)'),
(1405, 1, 14, 5, 0, 0, 'Echo Isles', 'The Echo Isles off Durotar''s southern coast were the Darkspear''s first home in Kalimdor, and they are lost to them now. The witch doctor Zalazane rules the largest isle from among his huts, surrounded by trolls he has hexed and bound to his will. In a circle of power on the largest isle he keeps a ring of skulls, one of them holding the trapped spirit of a slain Darkspear, and tainted fetishes called ju-ju heaps foul the flow of magic across the land. Yet the wild life of the isles goes on: Durotar tigers hunt in the shade of the trees, bloodtalon raptors bury their eggs in the sand, and makrura and crawlers crowd the shallows.', 'warcraft.wiki.gg/wiki/Echo_Isles (Darkspear settled after the Third War, Zalazane''s betrayal, ju-ju heaps); quest 826 description (once home, hexes our people, former Darkspear trolls); quest 808 description (circle of power on the largest isle, Minshina''s spirit trapped in his skull); quest 1884 description (ju-ju heaps among his huts on the main isle); quests 815, 817, 818 (taillasher eggs, tigers, makrura and crawlers); DB spawns in area 368: Zalazane 3205, Hexed Troll 3207, Voodoo Troll 3206, Durotar Tiger, Bloodtalon Taillasher, Taillasher Eggs, Ju-Ju Heap 102986; DB: makrura and crawler spawns in area 368 (75)'),
(1406, 1, 14, 6, 0, 0, 'Kolkar Crag', 'Over the ridge west of Sen''jin Village lies Kolkar Crag, a gorge where Kolkar centaurs have made their camp. They are not content to stay there. The scout Lar Prowltusk crept into the camp during one of their raids and learned that the centaurs mean to strike Durotar in three places at once: the Valley of Trials, Sen''jin Village and the gates of Orgrimmar itself. Each plan is held by a different leader of the camp, and the whole host answers to Warlord Kolkanis. The trolls and orcs would likely win such a war, but at a cost in blood they would rather not pay.', 'quest 786 description and reward text (ridge to the west, three-tiered attack, plans divided among three leaders, spared unnecessary bloodshed); gameobjects 3189, 3190, 3192 (Attack Plan: Valley of Trials, Sen''jin Village, Orgrimmar) in area 366; warcraft.wiki.gg/wiki/Kolkar_Crag (gorge, Kolkar forces led by Warlord Kolkanis); DB: Warlord Kolkanis 5808 in area 366'),
(1407, 1, 14, 7, 0, 0, 'Razor Hill', 'Razor Hill stands at the crossroads of central Durotar, an orc town under the command of Gar''Thok, whose barracks is the largest building in the place. Soon after the orcs came to these shores, Kul Tiran agents lured Thrall to a false parley here, and it was Rexxar who went in his stead and defeated the assassins waiting there. Today recruits fresh from the Valley pass through on their way into the wider land. Orgnil Soulscar hunts demon cultists from here, an old veteran watches from the tower with his signal horn, and the inn offers a fire and a place to boast of battles.', 'warcraft.wiki.gg/wiki/Razor_Hill (crossroads in central Durotar, barracks most prominent, Kul Tiran summit ambush, Rexxar in Thrall''s place); warcraft.wiki.gg/wiki/Orgnil_Soulscar (gossip: refuge for young orcs and trolls and traders); quest 830 (Gar''Thok, commander of Razor Hill); quest 823 (Orgnil polices Durotar); quest 791 description (Furl Scornbrow watches for invaders, signal horn); npc_text 938 (Innkeeper Grosk)'),
(1408, 1, 14, 8, 0, 0, 'Tiragarde Keep', 'Admiral Daelin Proudmoore built this keep on Durotar''s eastern coast when he brought the fleet of Kul Tiras against the orcs. The Horde broke his offensive and the keep fell, and the admiral himself died at Theramore. But his reserves under Lieutenant Benedict came back and took it again, and Kul Tiran sailors and marines now hold the walls with Watch Commander Zalaphil keeping guard. To the orcs this is a betrayal of the pact Thrall made with Jaina Proudmoore against Archimonde, and the keep sits like a splinter in the side of their homeland.', 'warcraft.wiki.gg/wiki/Tiragarde_Keep (hastily built by Daelin, fell, Benedict retook it, Zalaphil); quest 784 description (pact with Jaina, reserves led by Benedict retook the keep); DB spawns in area 372: Kul Tiras Sailor 3128, Kul Tiras Marine 3129, Lieutenant Benedict 3192, Watch Commander Zalaphil 5809'),
(1409, 1, 14, 9, 0, 0, 'Scuttle Coast', 'Along the shore north and east of Tiragarde Keep, the rocks are littered with the bones of Proudmoore''s fleet, broken on the rocks during the war with the Horde. The wrecks still hold their stores, and among them lie toolboxes of gnomish make, full of the clever devices the Alliance uses to build its machines. Gar''Thok wants them hauled ashore and sent to Orgrimmar so the Horde may learn how its enemies work. Salvagers must reckon with the makrura and surf crawlers that scuttle along the beach, and with the sand sharks that patrol the waters beyond.', 'warcraft.wiki.gg/wiki/Scuttle_Coast (Kul Tiras ships smashed on the rocks, orcs salvaging gnome technology); quest 825 description and reward text (wreckage east of Tiragarde Keep, tools of the Alliance, sent to Orgrimmar); DB in area 373: Gnomish Toolbox 3236 x20, Makrura Clacker, Makrura Shellhide, Pygmy Surf Crawler, Sand Shark 5435'),
(1410, 1, 14, 10, 0, 0, 'Razormane Grounds', 'West of Razor Hill, where brambles sprout from the red hills and old bones bleach in the sun, the Razormane quilboar still cling to Durotar. When the orcs arrived the quilboar held much of this land, and though the orcs have driven out most of them, their fortified camps here keep spitting out scouts, dustrunners and battleguards. Geolord Mottle, who wraps himself in lightning and mends wounds with healing waves, leads among them with Captain Flat Tusk of the battleguard. Gar''Thok will allow the quilboar no hold at all on orc land, and he dreams of one day clearing them from the whole of Kalimdor.', 'quest 837 description and reward text (quilboar held much land, camps west of Razor Hill, brambles, today Durotar tomorrow Kalimdor); warcraft.wiki.gg/wiki/Razormane_Grounds (brambles, bones, Geolord Mottle and Captain Flat Tusk led the encampment); DB in area 816: Razormane Quilboar, Scout, Dustrunner, Battleguard, Geolord Mottle 5826; Captain Flat Tusk 5824 nearby; smart_scripts 5826 (Lightning Shield, Healing Wave)'),
(1411, 1, 14, 11, 0, 0, 'Shrine of the Dormant Flame', 'From the banks of the Southfury, before the river meets the sea, a hidden trail winds up one of the highest peaks in Durotar. At the summit is the Shrine of the Dormant Flame, most holy to the shaman of the Horde. Its keeper, the troll Telf Joolam, turns away the treasure seekers who climb up expecting riches and find only an empty shrine. To shaman who come bearing the proper torch he reveals its secret: after drinking the fire sapta, they may see and face the flame''s manifestation at the peak, and kindle their torch at its brazier.', 'quest 1524 description (hidden trail along the Southfury before the Great Sea, highest peak, Telf Joolam); quest 1524 reward text (adventurers turned away from a seemingly empty shrine); quests 1525, 1526 descriptions and reward texts (fire sapta, manifestation, brazier, torch); warcraft.wiki.gg/wiki/Shrine_of_the_Dormant_Flame (most holy to all shaman of the Horde); DB: Telf Joolam 5900, Brazier of the Dormant Flame 61934, Minor Manifestation of Fire 5893 in area 640'),
(1412, 1, 14, 12, 0, 0, 'Southfury River', 'The Southfury River runs down from the north to the sea and marks Durotar''s western border with the Barrens, with the orc garrison of Far Watch Post standing just across. Its banks are the hunting grounds of the dreadmaw crocolisks, and they have claimed at least one proud young hunter. Misha Tor''kren''s son Kron went west to hunt them and never came home. Along its lower reaches, near where the river meets the Great Sea, a hidden trail climbs to the Shrine of the Dormant Flame.', 'warcraft.wiki.gg/wiki/Southfury_River (border between the Barrens and Durotar, empties into the Great Sea); quest 816 description (Kron hunting crocolisks along Southfury River); quest 809 description (Far Watch Post on the border of the Barrens to the west); quest 1524 description (hidden trail along the Southfury before the Great Sea); DB: Dreadmaw Crocolisk 3110 x25 in area 814'),
(1413, 1, 14, 13, 0, 0, 'Tor''kren Farm', 'Tor''kren Farm is a modest pig farm in northwestern Durotar, below Thunder Ridge, worked by the orc Misha Tor''kren. She once kept it with her son Kron, a strong youth whose stubborn pride got him into trouble. When she warned him that the crocolisks of the Southfury were too dangerous, he stormed off west to hunt them, and days passed without word. Misha waits at the farm still, wanting at least some sign of his fate so she can begin to mourn, and keeping a gift she had meant to give him on his return.', 'quest 816 description, request and reward texts (Kron, stubborn pride, crocolisks, gift); warcraft.wiki.gg/wiki/Tor''kren_Farm (northwestern Durotar, southeast of Thunder Ridge, pig farm run with her son); DB: Misha Tor''kren 3193 and Swine 10685 in area 2979'),
(1414, 1, 14, 14, 0, 0, 'Thunder Ridge', 'Thunder Ridge is a gorge in northwestern Durotar, southwest of Orgrimmar, where herds of thunder lizards and crackling lightning hides roam. It was once wooded, until human loggers began stripping it in the first days of the orcs'' settlement. Now the Burning Blade has come. The goblin warlock Fizzle Darkstorm keeps a camp in the ridge with fanatics and apprentices of the cult, spreading chaos from it, and Orgnil Soulscar of Razor Hill wants him dead. Horde warriors also come here to prove their toughness against the lizards.', 'warcraft.wiki.gg/wiki/Thunder_Ridge (gorge in northwestern Durotar southwest of Orgrimmar, ancient forest, human lumber operation, thunder lizards); quest 806 description (Fizzle Darkstorm, Burning Blade warlock, camped in Thunder Ridge with cultists); quest 1498 description (warriors prove toughness against thunder lizards); DB in area 369: Thunder Lizard 3130, Lightning Hide 3131, Fizzle Darkstorm 3203, Burning Blade Fanatic and Apprentice'),
(1415, 1, 14, 15, 0, 0, 'Razorwind Canyon', 'A long canyon runs through the hills north of Razor Hill, and the supply caravans that use it have learned to fear it. Dustwind harpies swoop from the walls, pillage the wagons and leave the stolen sacks strewn about their roosts. Rezlak of the Tinkers'' Union, one of Gazlowe''s goblins sent to help the orcs build, lost his last shipment this way and can get nothing done without it. Through the canyon''s eastern side lies Drygulch Ravine, where the harpies nest in greater numbers still.', 'quest 834 description and reward text (Rezlak, Gazlowe''s man, caravan snatched by Dustwind harpies of Razorwind Canyon); quest 835 description (Drygulch Ravine lies through the eastern part of Razorwind Canyon); DB in area 410: Dustwind Harpy 3115, Dustwind Pillager 3116, Stolen Supply Sack 3290 x10'),
(1416, 1, 14, 16, 0, 0, 'Drygulch Ravine', 'Drygulch Ravine is a deep cleft reached through the eastern side of Razorwind Canyon, and it is the true nest of the Dustwind harpies. Savages and storm witches of the flock hold its floor and cliffs, and as long as they thrive no caravan in the region is safe. Rezlak of the Tinkers'' Union would see every one of them dead. The harpies are not the only danger. In Dustwind Cave, high above the ravines, cultists of the Burning Blade gather with neophytes and thugs of the cult, and they too carry its searing collars.', 'quest 835 description (Drygulch Ravine through eastern Razorwind Canyon, kill the harpies to secure the routes); warcraft.wiki.gg/wiki/Drygulch_Ravine (harpies nest on the cliffs, banditry); warcraft.wiki.gg/wiki/Dustwind_Cave (Burning Blade trains new members under cultists; thugs, cultists, neophytes); quest 1525 description (cultists in a cave above the ravines northeast of Razor Hill); DB in area 370: Dustwind Savage 3117, Dustwind Storm Witch 3118, Burning Blade Cultist, Neophyte, Thug; creature_loot: they drop Searing Collar 4871'),
(1417, 1, 14, 17, 0, 0, 'Skull Rock', 'Skull Rock is a cave in the mountains just east of Orgrimmar, close enough to the capital to alarm anyone who learns what lies inside. It shelters the largest band of the Burning Blade in Durotar. Within, the cultists perform their rites and burn their own flesh with searing collars, which seem to attune them to demonic power. The orc warlock Gazz''uz leads them, and a rarely seen felweaver called Scornn stalks the tunnels. Warlocks of the cult have even stolen from the Horde''s own warlocks and hidden their prize here.', 'quest 828 description (cave in the mountains just outside Orgrimmar, large band of cultists); quest 827 description (vile rituals, Searing Collars, attune to demonic power); quest 1501 description (Tablet of Verga stolen by Burning Blade warlocks, kept at Skull Rock east of the city); warcraft.wiki.gg/wiki/Skull_Rock (leader is the orc warlock Gazz''uz); DB in area 817: Burning Blade Fanatic, Apprentice, Felweaver Scornn 5822'),
(1418, 1, 14, 18, 0, 0, 'Rocktusk Farm', 'Rocktusk Farm is a pig farm on the western road out from Orgrimmar''s gates, where swine root in their pens under the walls of the capital. The venomtail scorpids that hunt near the city entrance are among the deadliest in Durotar, as the Darkspear Rhinag learned when he hunted them without an antidote and one stung him deeply. Too weak to return to Sen''jin and too ashamed to want to, he now waits here for an antidote from Kor''ghan of the Cleft of Shadow, dreading the further rituals Kor''ghan will put him through once he recovers.', 'warcraft.wiki.gg/wiki/Rocktusk_Farm (down the western road outside Orgrimmar''s gates, pig farm); quest 812 description and request/reward texts (Rhinag stung by venomtails, ashamed to return to Sen''jin, Kor''ghan''s rituals); quest 813 description (venomtails near the entrance of Orgrimmar, deadliest scorpids); DB: Rhinag 3190 (faction 126 Darkspear) and Swine 10685 in area 1296'),
(1419, 2, 14, 1, 2, 0, 'Gar''Thok', 'Gar''Thok commands Razor Hill and greets visitors with little patience for talk and much for work. In the first days of Durotar he was at an orc outpost when sailors of Kul Tiras fell on it and slaughtered his men. He survived, and he has not forgotten. He never trusted the humans even while fighting beside them, and he sends young warriors against the Kul Tiran holdouts at Tiragarde Keep and to salvage gnomish tools from Proudmoore''s wrecks. He means to clear the Razormane from Durotar as well.', 'quest_greeting 3139 (little time for talk and much work); warcraft.wiki.gg/wiki/Gar''Thok (guarded the orc base at Mount Hyjal, outpost attacked by Kul Tiras sailors who killed his men); quest 831 description (humans cannot be trusted, fought alongside them with a weary heart); quests 784, 825, 837 (Tiragarde, wreckage, Razormane)'),
(1420, 2, 14, 2, 2, 0, 'Orgnil Soulscar', 'Orgnil Soulscar is the orc who polices Durotar against evils of the spirit, and above all against the Burning Blade. He keeps watch from Razor Hill, and he swears that no servant of demons will be suffered in the land. When word reached him that the cult had crept into the Valley of Trials, his alarm was plain: the Burning Blade was spreading. He tracked down the warlock Fizzle Darkstorm in Thunder Ridge, and he turns to the shaman Margoz for counsel on the cult''s deeper secrets.', 'quest 823 description (polices Durotar from evils such as the Burning Blade); warcraft.wiki.gg/wiki/Orgnil_Soulscar (gossip: Razor Hill as refuge, his job to keep it that way); creature_text 3142 (no demon''s servant in our lands; the Burning Blade is spreading); quests 806, 828 descriptions'),
(1421, 2, 14, 3, 2, 0, 'Master Gadrin', 'Master Gadrin is the aged witch doctor who speaks for Sen''jin Village, and he bids those who would talk with him to come and sit at his side. His grief is personal. Zalazane took his brother Minshina and killed him, then chained the spirit inside its own skull, and Gadrin hears it calling to him in his dreams. He wants Zalazane''s reign over the Echo Isles ended so that the tribe can sleep in peace. Behind him his assistant Bom''bay, working his way through witch doctor school, mends the ailing, and Gadrin''s knowledge of troll lore runs deep enough that he knows the whispered true name of the Witherbark spider god.', 'warcraft.wiki.gg/wiki/Master_Gadrin (chief witch doctor, mentored Vol''jin and Zalazane); quest 808 description (Minshina taken and killed by Zalazane, spirit trapped in his skull, dreams); quest_greeting 3188 (come, sit by me); npc_text 3794, 3795 (Bom''bay, Gadrin''s assistant, witch doctor school); quest 2936 reward text (Elortha no Shadra; the Hinterlands entry tells this story)'),
(1422, 2, 14, 4, 0, 0, 'Zalazane', 'Zalazane is a witch doctor of the Darkspear who turned on his own tribe. When the trolls settled the Echo Isles after helping the Horde against Proudmoore, he used dark voodoo to rob most of them of their will and bend them to his service, and the free Darkspear had to abandon the isles for the mainland. He was not content to let them go. From his huts on the largest isle he sends hexed trolls across the water to drag more of his kin under his sway. He killed Gadrin''s brother Minshina and chained the spirit in its skull, and his tainted ju-ju heaps foul the flow of magic across Durotar.', 'warcraft.wiki.gg/wiki/Zalazane (trained under Gadrin, Vol''jin''s childhood friend, driven mad by power, enslaved Darkspear, Vol''jin ordered the free trolls to abandon the islands); warcraft.wiki.gg/wiki/Echo_Isles (repeated attempts failed as he faked his own deaths); quest 826 description (sends trolls to the mainland to hex our people); quest 808 (Minshina''s skull); quest 1884 (ju-ju heaps)'),
(1423, 2, 14, 5, 2, 0, 'Lieutenant Benedict', 'Lieutenant Benedict commands the reserves of Kul Tiras that Admiral Proudmoore left behind. After the admiral''s death and the fall of Tiragarde Keep, Benedict brought his men back and retook it, and he holds it still with sailors and marines who guard his belongings jealously. To the orcs he is the living proof that humans honor no treaty. In a chest he keeps close lie sealed orders under the admiral''s own seal, showing that Proudmoore''s plans were laid well before his death and that more of his men may yet land on Durotar''s shores.', 'quest 784 description (Admiral''s reserves led by Benedict retook the keep, no respect for diplomacy); warcraft.wiki.gg/wiki/Tiragarde_Keep (Benedict sent to retake the keep under the Admiral''s special orders); creature_text 3129 (Step away from the Lieutenant''s belongings); quests 830, 831 descriptions (aged envelope with Proudmoore''s seal from Benedict''s Chest 3239; plans laid before his death; next waves)'),
(1424, 2, 14, 6, 2, 0, 'Margoz', 'Margoz is an orc shaman who keeps a camp in northeastern Durotar, between the coast and Drygulch Ravine. He knows more of the Burning Blade''s corruption than most, and Orgnil Soulscar values his counsel. Margoz believes the cultists'' searing collars bind them to demonic power, and he has tried to read their secrets in a trance, only to be burned by the magic he unleashed. Admitting the task is beyond a shaman, he sends the collars to the warlock Neeru Fireblade in Orgrimmar, uneasy about whether Neeru''s craft is as harmless as he claims.', 'quest 828 description (one of our Shamans, knows more of the corruption, camped northeast between coast and Drygulch Ravine); quest 827 description (collars attune to demonic power); creature_text 3208 (enters a trance, burned by unleashed magic, secret beyond my skills); quest 829 description (warlock needed; Neeru professes his research is benign, be that true or false)'),
(1425, 2, 14, 7, 0, 0, 'Gazz''uz', 'Gazz''uz is the orc warlock who leads the Burning Blade at Skull Rock, a small rebellion festering on the doorstep of Orgrimmar. He wears a pendant called the Eye of Burning Shadow, and through it an unseen voice speaks to him, demanding reports and warning him to prepare for an attack. Strangest of all, the voice threatens to set Neeru Fireblade on him if he will not answer. When the pendant was carried to Neeru, the warlock found it curious that the cult singled him out, and stranger still that the Burning Blade bears a name so close to his own.', 'warcraft.wiki.gg/wiki/Gazz''uz (orc warlock of the Burning Blade at Skull Rock; small rebellion on Orgrimmar''s outskirts); creature_loot: Gazz''uz 3204 drops Eye of Burning Shadow 4903, which starts quest 832; quest 832 description and reward text (voice demanding a report, threat of Neeru Fireblade, Neeru''s reaction)'),
(1426, 3, 14, 1, 2, 0, 'Of Age in the Valley', 'Every young orc and troll of Durotar begins in the Valley of Trials. Kaltunk looks each recruit over, laughs at their dreams of strangling dragons, and sends them to Gornek in the Den, who sighs at what the Horde has come to and sets them on boars and then on scorpids, whose antidote is made from their own venom. Smaller trials teach other lessons. Foreman Thazz''ril hands out a blackjack to wake the peons who nap among the trees, Galgar trades his famous cactus apple treat for the fruit, and a frightened peon begs someone braver to carry his food back to Razor Hill. Beneath a tree lies the wounded Hana''zua, struck down by the scorpid Sarkoth on a plateau to the south, asking only that his honor be upheld. Gornek is impressed by any recruit who will fight for a stranger''s honor, and he sends aid to the wounded orc.', 'quests 4641, 788, 789 (descriptions and reward texts); quests 790, 804 (Hana''zua and Sarkoth); quest 5441 (lazy peons); quest 4402 (Galgar); quest 2161 (Ukor''s food to Razor Hill); npc_text 3583 (Gornek on the valley)'),
(1427, 3, 14, 2, 2, 0, 'Taint in the Valley', 'Zureetha Fargaze came to the Valley of Trials to guide young recruits and found something rotten there. A group calling itself the Burning Blade had made a coven in the caves of the valley''s northern cliffs, and its vile familiars were spilling out to cause havoc. She sent recruits to thin the imps first, then, guided by her divinations, sent them deep into the coven after a medallion of power held by the warlock Yarrog Baneshadow. The medallion was recovered, but Zureetha feared the cult had further aims in Durotar and that the coven was only the herald of a larger threat. She sent word to Master Gadrin at Sen''jin Village, who reported that the Burning Blade had not reached his village, though Zalazane''s evil had taken root on the Echo Isles.', 'quests 792, 794, 805 (descriptions and reward texts); creature_loot: Yarrog Baneshadow 3183 drops Burning Blade Medallion 4859'),
(1428, 3, 14, 3, 2, 0, 'Hunting the Burning Blade', 'From Sen''jin, word of the cult went to Orgnil Soulscar in Razor Hill, who cried out that the Burning Blade was spreading and resolved to root it out. His own investigations had found the goblin warlock Fizzle Darkstorm camped in Thunder Ridge with his cultists, and his dead claw was soon brought back as proof. Next Orgnil sent his agents to the shaman Margoz, who told of a large band at Skull Rock, in the mountains just outside Orgrimmar, where cultists burned their flesh with searing collars. Margoz could not unlock the collars'' secrets, so one was carried to the warlock Neeru Fireblade in the Cleft of Shadow. Neeru declared that the cult rallied around an object of demonic power called the Demon Seed, hidden in the Barrens, and that it must be destroyed.', 'quests 823, 806, 828, 827, 829, 809 (descriptions and reward texts); creature_text 3142 (the Burning Blade is spreading; smashes the dead, twisted claw); creature_text 3208 (Margoz burned by the magic)'),
(1429, 3, 14, 4, 2, 0, 'The Exile of the Darkspear', 'The Echo Isles were home to the Darkspear until their own witch doctor, Zalazane, turned his voodoo on them. Driven to the mainland, the tribe still suffers him. Master Gadrin hears his dead brother Minshina calling in his dreams, his spirit chained in his own skull among others in a circle of power on the largest isle, and he begs for the skull to be brought back so the spirit can go free. Gadrin wants Zalazane himself destroyed too, along with the hexed and voodoo trolls who were once Darkspear, so that the tribe may sleep in peace. The tribe''s mage Un''Thuwa senses a further wound: Zalazane''s ju-ju heaps, hidden among his huts, twist the flow of magic across Durotar, corrupting beasts and feeding demons, and must be smashed before the harm becomes lasting.', 'quests 808, 826 (descriptions and reward texts); creature_text 3188 (my brother thanks you); quest 1884 description and reward text (ju-ju heaps); quest 826 objectives: Hexed Troll 3207, Voodoo Troll 3206, Zalazane''s Head 4866'),
(1430, 3, 14, 5, 2, 0, 'Proudmoore''s Remnant', 'Admiral Proudmoore broke the peace that Thrall had made with his daughter Jaina against Archimonde, and though the admiral is dead, his soldiers are not gone. His reserves under Lieutenant Benedict retook Tiragarde Keep, and Gar''Thok sends warriors to drive them out and prove their honor. Gar''Thok also wants the wreckage of Proudmoore''s fleet searched for gnomish tools, so the Horde may learn how its enemies build their machines. From Benedict''s chest comes a weathered envelope bearing the admiral''s seal: orders that show his plans were laid before he died, and that more of his men may yet land. Gar''Thok, who never trusted the humans, has it carried at once to Vol''jin in Orgrimmar, who goes to counsel Thrall.', 'quests 784, 825, 830, 831 (descriptions and reward texts); gameobject 3239 Benedict''s Chest drops Aged Envelope 4881, which starts quest 830'),
(1431, 3, 14, 6, 2, 0, 'The Call of Earth', 'When a young orc or troll shaman in the Valley of Trials is ready, Canaga Earthcaller sends them to hunt the felstalkers for their hooves, and when they return he prepares a sapta, a draught that binds the drinker''s spirit to an element. It may only be drunk in a holy place, so the novice carries it down the Hidden Path to Spirit Rock. There the earth reveals itself, and asks only humility. From it the novice receives a piece of rough quartz, small but enduring, with counsel to be patient, stay strong and seek wisdom. Canaga sets the stone at the heart of the novice''s first earth totem, a focus for the powers the earth will grant as wisdom grows.', 'quests 1516, 1517, 1518 (descriptions and reward texts); DB: Canaga Earthcaller 5887 in the Valley of Trials; Minor Manifestation of Earth 5891 at Spirit Rock ends 1517 and starts 1518');
